// Fichier de simulation pour l'API Stripe
// Dans un vrai projet, ceci serait sur votre serveur backend

export default function handler(req, res) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const { priceId, userId, userEmail, planId, successUrl, cancelUrl } = req.body;

  // Simulation d'une session Stripe
  const sessionId = `cs_test_${Math.random().toString(36).substr(2, 9)}`;
  
  // Dans un vrai projet, vous utiliseriez l'API Stripe :
  /*
  const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
  
  const session = await stripe.checkout.sessions.create({
    payment_method_types: ['card'],
    line_items: [{
      price: priceId,
      quantity: 1,
    }],
    mode: 'subscription',
    success_url: successUrl,
    cancel_url: cancelUrl,
    customer_email: userEmail,
    metadata: {
      userId: userId,
      planId: planId,
    },
  });
  */

  // Simulation de la réponse
  res.status(200).json({
    id: sessionId,
    url: `https://checkout.stripe.com/pay/${sessionId}#`
  });
}